/* Stage an exact frontend/source copy into the initialized private Sites project. */
import fs from 'node:fs';import path from 'node:path';import {fileURLToPath} from 'node:url';import {execFileSync} from 'node:child_process';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..'),option=process.argv.indexOf('--target'),target=option>=0?path.resolve(process.argv[option+1]||''):null;if(!target||target===root||!fs.existsSync(path.join(target,'.openai/hosting.json')))throw Error('Pass --target with the initialized private Sites project folder.');
const declared=JSON.parse(fs.readFileSync(path.join(root,'preview-server/hosting.json'),'utf8')),current=JSON.parse(fs.readFileSync(path.join(target,'.openai/hosting.json'),'utf8'));if(current.project_id!==declared.project_id)throw Error('Private Site identity mismatch.');
function write(relative,content){const dest=path.resolve(target,relative);if(!dest.startsWith(target+path.sep))throw Error('Staging path escaped the target.');fs.mkdirSync(path.dirname(dest),{recursive:true});fs.writeFileSync(dest,content);}
function copy(source,destination){write(destination,fs.readFileSync(path.join(root,source)));}
const files=execFileSync('git',['ls-files','--cached','--others','--exclude-standard','-z'],{cwd:root,encoding:'utf8',maxBuffer:20e6}).split('\0').filter(Boolean),selected=[...new Set(files)].filter(f=>/^(?:[^/]+\.(?:html|css|js|webmanifest)|(?:students|assets|privacy|education|professionals)\/(?!.*(?:^|\/)\.)[^]*\.(?:html|css|js|json|svg|png|webp|jpe?g|ico|woff2?|md))$/.test(f));
for(const file of selected){if(fs.statSync(path.join(root,file)).size>25e6)throw Error('Static asset exceeds 25 MB: '+file);copy(file,'public/'+file);}
copy('workspace-core-20261030.js','workspace-core-20261030.js');copy('preview-server/workspace-service.mjs','lib/workspace-service.mjs');copy('preview-server/db/schema.ts','db/schema.ts');copy('preview-server/routes/workspace-route.ts','app/api/workspace/[...path]/route.ts');copy('preview-server/routes/live-route.ts','app/live-api/[...path]/route.ts');copy('preview-server/routes/page.tsx','app/page.tsx');copy('preview-server/routes/layout.tsx','app/layout.tsx');for(const file of files.filter(f=>f.startsWith('preview-server/drizzle/')))copy(file,file.replace('preview-server/',''));write('.openai/hosting.json',JSON.stringify({...current,...declared},null,2)+'\n');
write('public/_headers','/*\n  X-Robots-Tag: noindex, nofollow\n  Cache-Control: no-store\n  X-Content-Type-Options: nosniff\n');
const head=execFileSync('git',['rev-parse','HEAD'],{cwd:root,encoding:'utf8'}).trim();write('source-provenance.json',JSON.stringify({repository:'tmwalterfang-del/marine-tools',branch:'feature/education-next',sourceBaseCommit:head,stagedAt:new Date().toISOString(),files:selected.length},null,2)+'\n');
console.log(JSON.stringify({status:'staged',target,frontendFiles:selected.length,projectId:declared.project_id,sourceBaseCommit:head}));
